import React, { useState, useEffect } from 'react';

const Gallery = () => {
  const [galleryData, setGalleryData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedImage, setSelectedImage] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbwrXGCVVbNYuChToZTUe7TCn7gRy5q2pkVuxIR7V4JFSHnUEdKckQXNlvQ-zZPdcu/exec';

  useEffect(() => {
    fetchGalleryData();
  }, []);

  const fetchGalleryData = async () => {
    try {
      setLoading(true);
      setError(null);
      
      // Use no-cors mode for Google Apps Script
      const response = await fetch(`${SCRIPT_URL}?t=${Date.now()}`, {
        method: 'GET',
        mode: 'no-cors', // This is key for Google Apps Script
        headers: {
          'Content-Type': 'application/json',
        }
      });
      
      // With no-cors mode, response.ok will always be false
      // We need to handle the response differently
      const text = await response.text();
      
      // Try to parse the response
      let result;
      try {
        result = JSON.parse(text);
      } catch (parseError) {
        // If parsing fails, it might be due to CORS restrictions
        // Try alternative approach using JSONP or proxy
        throw new Error('Failed to parse response. CORS issue detected.');
      }
      
      if (result && result.success) {
        // Transform the data to match our expected structure
        const transformedData = result.data.map((item, index) => ({
          imageNo: item[0] || index + 1,
          imageUrl: item[1] || '',
        })).filter(item => item.imageUrl);
        
        setGalleryData(transformedData);
      } else {
        throw new Error(result?.error || 'Failed to fetch data');
      }
    } catch (err) {
      // Fallback: Try with JSONP approach or proxy
      fetchWithJSONP();
    }
  };

  // Alternative JSONP approach for CORS issues
  const fetchWithJSONP = () => {
    const callbackName = 'jsonp_callback_' + Date.now();
    const script = document.createElement('script');
    
    window[callbackName] = (data) => {
      delete window[callbackName];
      document.body.removeChild(script);
      
      if (data && data.success) {
        const transformedData = data.data.map((item, index) => ({
          imageNo: item[0] || index + 1,
          imageUrl: item[1] || '',
        })).filter(item => item.imageUrl);
        
        setGalleryData(transformedData);
        setLoading(false);
      } else {
        setError(data?.error || 'Failed to fetch data via JSONP');
        setLoading(false);
      }
    };

    script.src = `${SCRIPT_URL}?callback=${callbackName}&t=${Date.now()}`;
    document.body.appendChild(script);
  };

  // Alternative: Use a CORS proxy
  const fetchWithCorsProxy = async () => {
    try {
      const proxyUrl = 'https://cors-anywhere.herokuapp.com/'; // Public CORS proxy
      const response = await fetch(`${proxyUrl}${SCRIPT_URL}?t=${Date.now()}`);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const result = await response.json();
      
      if (result.success) {
        const transformedData = result.data.map((item, index) => ({
          imageNo: item[0] || index + 1,
          imageUrl: item[1] || '',
        })).filter(item => item.imageUrl);
        
        setGalleryData(transformedData);
      } else {
        throw new Error(result.error || 'Failed to fetch data');
      }
    } catch (err) {
      setError(err.message);
      console.error('Error fetching via proxy:', err);
    } finally {
      setLoading(false);
    }
  };

  // Updated fetch function with better error handling
  const fetchGalleryDataImproved = async () => {
    try {
      setLoading(true);
      setError(null);
      
      // First try: Regular fetch (might fail due to CORS)
      try {
        const response = await fetch(`${SCRIPT_URL}?t=${Date.now()}`);
        
        if (response.ok) {
          const result = await response.json();
          handleSuccessResponse(result);
          return;
        }
      } catch (directError) {
        console.log('Direct fetch failed, trying no-cors...');
      }
      
      // Second try: no-cors mode
      try {
        const response = await fetch(`${SCRIPT_URL}?t=${Date.now()}`, {
          mode: 'no-cors',
          credentials: 'omit'
        });
        
        // no-cors mode doesn't allow reading the response
        // This will likely fail, so we'll move to JSONP
        throw new Error('no-cors mode not sufficient for reading response');
      } catch (noCorsError) {
        console.log('no-cors failed, trying JSONP...');
      }
      
      // Third try: JSONP
      fetchWithJSONP();
      
    } catch (err) {
      setError(err.message);
      setLoading(false);
    }
  };

  const handleSuccessResponse = (result) => {
    if (result.success) {
      const transformedData = result.data.map((item, index) => ({
        imageNo: item[0] || index + 1,
        imageUrl: item[1] || '',
      })).filter(item => item.imageUrl);
      
      setGalleryData(transformedData);
    } else {
      throw new Error(result.error || 'Failed to fetch data');
    }
    setLoading(false);
  };

  // Convert Google Drive file URL to thumbnail URL
  const getThumbnailUrl = (driveUrl) => {
    if (!driveUrl) return '';
    
    try {
      const fileIdMatch = driveUrl.match(/\/d\/([^\/]+)/) || driveUrl.match(/id=([^&]+)/);
      const fileId = fileIdMatch ? fileIdMatch[1] : null;
      
      if (!fileId) {
        console.warn('Could not extract file ID from URL:', driveUrl);
        return driveUrl;
      }
      
      return `https://drive.google.com/thumbnail?id=${fileId}&sz=w400`;
    } catch (error) {
      console.error('Error processing drive URL:', error);
      return driveUrl;
    }
  };

  // Convert Google Drive file URL to direct download URL for full-size image
  const getFullSizeUrl = (driveUrl) => {
    if (!driveUrl) return '';
    
    try {
      const fileIdMatch = driveUrl.match(/\/d\/([^\/]+)/) || driveUrl.match(/id=([^&]+)/);
      const fileId = fileIdMatch ? fileIdMatch[1] : null;
      
      if (!fileId) return driveUrl;
      
      return `https://drive.google.com/uc?export=view&id=${fileId}`;
    } catch (error) {
      console.error('Error processing drive URL:', error);
      return driveUrl;
    }
  };

  // Check if URL is a Google Drive URL
  const isGoogleDriveUrl = (url) => {
    return url && url.includes('drive.google.com');
  };

  const openModal = (item) => {
    const imageUrl = item.imageUrl;
    setSelectedImage({
      ...item,
      thumbnailUrl: isGoogleDriveUrl(imageUrl) ? getThumbnailUrl(imageUrl) : imageUrl,
      fullSizeUrl: isGoogleDriveUrl(imageUrl) ? getFullSizeUrl(imageUrl) : imageUrl
    });
    setIsModalOpen(true);
    document.body.style.overflow = 'hidden';
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setSelectedImage(null);
    document.body.style.overflow = 'unset';
  };

  // Handle keyboard events
  useEffect(() => {
    const handleEscape = (e) => {
      if (e.key === 'Escape' && isModalOpen) {
        closeModal();
      }
    };

    window.addEventListener('keydown', handleEscape);
    return () => window.removeEventListener('keydown', handleEscape);
  }, [isModalOpen]);

  // Handle click outside modal
  const handleBackdropClick = (e) => {
    if (e.target === e.currentTarget) {
      closeModal();
    }
  };

  // Update your useEffect to use the improved function
  useEffect(() => {
    fetchGalleryDataImproved();
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 py-8 px-4">
        <div className="max-w-7xl mx-auto text-center">
          <div className="text-2xl font-bold text-gray-800 mb-4">🖼️ Photo Gallery</div>
          <div className="text-lg text-gray-600 mb-4">Loading photos...</div>
          <div className="animate-pulse grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {[...Array(8)].map((_, i) => (
              <div key={i} className="bg-gray-300 rounded-2xl h-64"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 py-8 px-4">
        <div className="max-w-7xl mx-auto text-center">
          <div className="bg-red-50 border border-red-200 rounded-2xl p-6 max-w-md mx-auto">
            <h3 className="text-red-800 text-xl font-semibold mb-2">Error Loading Photos</h3>
            <p className="text-red-600 mb-4">{error}</p>
            <div className="space-y-2">
              <button 
                onClick={fetchGalleryDataImproved}
                className="bg-blue-500 hover:bg-blue-600 text-white px-6 py-2 rounded-lg transition-colors block w-full"
              >
                Try Again
              </button>
              <button 
                onClick={fetchWithCorsProxy}
                className="bg-green-500 hover:bg-green-600 text-white px-6 py-2 rounded-lg transition-colors block w-full"
              >
                Use Proxy (Alternative)
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <>
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 py-8 px-4">
        <div className="max-w-7xl mx-auto">
          {/* Header */}
          <div className="text-center mb-8">
            <h1 className="text-4xl font-bold text-gray-800 mb-2">🖼️ Photo Gallery</h1>
            <p className="text-lg text-gray-600">
              {galleryData.length} beautiful photos
            </p>
          </div>

          {/* Masonry Grid */}
          {galleryData.length === 0 ? (
            <div className="text-center bg-white rounded-2xl p-12 shadow-lg">
              <p className="text-xl text-gray-600">No photos found</p>
              <button 
                onClick={fetchGalleryDataImproved}
                className="mt-4 bg-blue-500 hover:bg-blue-600 text-white px-6 py-2 rounded-lg"
              >
                Refresh
              </button>
            </div>
          ) : (
            <div className="columns-1 sm:columns-2 md:columns-3 lg:columns-4 gap-6 space-y-6">
              {galleryData.map((item, index) => {
                const imageUrl = item.imageUrl;
                const thumbnailUrl = isGoogleDriveUrl(imageUrl) ? getThumbnailUrl(imageUrl) : imageUrl;
                
                return (
                  <div 
                    key={index} 
                    className="break-inside-avoid bg-white rounded-2xl shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-1 overflow-hidden group cursor-pointer"
                    onClick={() => openModal(item)}
                  >
                    <div className="relative overflow-hidden">
                      <img 
                        src={thumbnailUrl} 
                        alt={`Photo ${item.imageNo}`}
                        loading="lazy"
                        className="w-full h-64 object-cover transition-transform duration-500 group-hover:scale-105"
                        onError={(e) => {
                          e.target.src = 'https://images.unsplash.com/photo-1554629947-334ff61d85dc?w=400&h=300&fit=crop';
                        }}
                      />
                      <div className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-10 transition-all duration-300"></div>
                    </div>
                    <div className="p-4">
                      <p className="text-sm font-medium text-gray-700">
                        <span className="text-blue-600">Photo</span> #{item.imageNo}
                      </p>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        <style jsx>{`
          .columns-1 > *,
          .sm\:columns-2 > *,
          .md\:columns-3 > *,
          .lg\:columns-4 > * {
            display: inline-block;
            width: 100%;
          }
          
          .break-inside-avoid {
            break-inside: avoid;
            page-break-inside: avoid;
          }
        `}</style>
      </div>

      {/* Modal Dialog */}
      {isModalOpen && selectedImage && (
        <div 
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black bg-opacity-75 backdrop-blur-sm"
          onClick={handleBackdropClick}
        >
          <div className="relative max-w-7xl max-h-full w-full h-full flex items-center justify-center">
            <button
              onClick={closeModal}
              className="absolute top-4 right-4 z-10 bg-white hover:bg-gray-100 text-gray-800 rounded-full w-10 h-10 flex items-center justify-center shadow-lg transition-all duration-200 hover:scale-110"
              aria-label="Close modal"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>

            <div className="relative bg-white rounded-2xl overflow-hidden shadow-2xl max-w-5xl w-full max-h-[90vh]">
              <img 
                src={selectedImage.fullSizeUrl} 
                alt={`Photo ${selectedImage.imageNo}`}
                className="w-full h-auto max-h-[85vh] object-contain"
                onError={(e) => {
                  e.target.src = 'https://images.unsplash.com/photo-1554629947-334ff61d85dc?w=1200&h=800&fit=crop';
                }}
              />
              
              <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black via-black/70 to-transparent p-6 text-white">
                <div className="flex justify-between items-end">
                  <div>
                    <h3 className="text-xl font-semibold mb-1">
                      Photo #{selectedImage.imageNo}
                    </h3>
                  </div>
                  <button
                    onClick={() => window.open(selectedImage.imageUrl, '_blank')}
                    className="bg-blue-500 hover:bg-blue-600 text-white px-4 py-2 rounded-lg transition-colors"
                  >
                    View Original
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default Gallery;
